/*
 * Leitura das configurações do tema que o extend.php serializa no fórum
 * (`canela*`). O PHP já converte booleanos e inteiros, mas o atributo pode
 * faltar por um instante logo depois de ativar a extensão — daí os padrões.
 */
import app from 'flarum/forum/app';
export function forumBool(attributeName, fallback = false) {
  // Nos initializers o `app.forum` ainda não existe: vale o padrão.
  if (!app.forum) return fallback;
  const value = app.forum.attribute(attributeName);
  return value === undefined || value === null ? fallback : !!value;
}
export function forumInt(attributeName, fallback) {
  if (!app.forum) return fallback;
  const value = Number(app.forum.attribute(attributeName));
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : fallback;
}

/** Atalho para a tradução do tema já como string (títulos, aria-label…). */
export function t(key, params = {}) {
  return app.translator.trans(`ramon-canela.forum.${key}`, params, true);
}
export function isExtensionEnabled(id) {
  return id in flarum.extensions;
}
flarum.reg.add('ramon-canela', 'forum/utils/settings', { forumBool: forumBool,forumInt: forumInt,t: t,isExtensionEnabled: isExtensionEnabled, });